//! 🌊️ Exact original Flow prefix and request survive all denied close currencies.
use semio_framework_job::{StepContext,root_cancel_token,Generation,OperationId,StepBudget};
use semio_framework_os_kernel as store;
use semio_framework_value::{retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep},RetirementDemand};
use semio_s_artifact_stdio_semio::standards::v1::subsets::flow::io::binary::snapshot::{SemioFlowSnapshotDecode,SemioFlowSnapshotDecodeStep};
use semio_s_artifact_stdio_semio::standards::v1::subsets::flow::schema::snapshot::SemioFlowSnapshot;
use store::{ArtifactPack,ErasedSnapshotRetirement,MemberOpenDiagnostic,MemberOpenRequest,MemberSnapshotOpenOperation,OwnedSchemaDecodeCredits,OwnedSchemaDecodePage,OwnedSchemaDecodePages};
#[global_allocator]
static FLOW_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🧾️original/🔣️.json")).unwrap()}
fn wires()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap()}
fn bytes(value:&str)->Vec<u8>{value.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
fn policy(f:&serde_json::Value)->RetainedCloneGrant{let p=&f["policy"];RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize}}
fn request(wire:&[u8],subset:&str)->MemberOpenRequest{
 let mut input=Vec::new();store::pack_rt::write_varint_u64(&mut input,wire.len()as u64);input.extend_from_slice(wire);input.push(83);
 let mut pages=OwnedSchemaDecodePages::try_with_credits(OwnedSchemaDecodeCredits{maximum_pages:input.len().div_ceil(4096),maximum_bytes:input.len()}).unwrap();for chunk in input.chunks(4096){pages.admit_page(OwnedSchemaDecodePage::try_from_slice(chunk).unwrap()).unwrap();}pages.seal().unwrap();
 let expected=semio_framework_artifact_reference::ArtifactRef{artifact_id:"original-flow 雪".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:subset.into()}};
 MemberOpenRequest::new(OperationId(1),Generation(1),1000,expected,None,pages,store::ActorId("original actor 雪".into())).admit(1).unwrap_or_else(|_|panic!("authored genuine request"))
}
fn demand(owner:&dyn ErasedSnapshotRetirement)->RetirementDemand{let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();owner.next_demand(if copy==0{release}else{copy}).unwrap()}
fn close(owner:&mut dyn ErasedSnapshotRetirement,grant:RetainedCloneGrant,rows:&mut Vec<serde_json::Value>)->(usize,usize){
 let mut born=0;let mut freed=0;let f=fixture();for turn in 0..100000{
  if owner.terminal_is_empty(){return(born,freed);}
  let d=demand(owner);assert!(d.copy_bytes<=grant.maximum_copy_bytes&&d.capacity_bytes<=grant.maximum_capacity_bytes&&d.release_bytes<=grant.maximum_release_bytes&&d.depth<=grant.maximum_depth);
  for row in f["denials"].as_array().unwrap(){let axis=row["axis"].as_str().unwrap();let mut denied=grant;let available=match axis{"items"=>{denied.maximum_items=0;1},"copy"=>{denied.maximum_copy_bytes=d.copy_bytes.saturating_sub(1);d.copy_bytes},"capacity"=>{denied.maximum_capacity_bytes=d.capacity_bytes.saturating_sub(1);d.capacity_bytes},"release"=>{denied.maximum_release_bytes=d.release_bytes.saturating_sub(1);d.release_bytes},_=>{denied.maximum_depth=d.depth.saturating_sub(1);d.depth}};if available==0{continue;}
   let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(denied));assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0),"denied {axis} changed original backing at turn{turn}");
   if row["refusal"]=="error"{assert!(result.is_err());}else{assert_eq!(result.unwrap().progress(),RetainedCloneProgress::default());}assert_eq!(demand(owner),d);assert!(!owner.terminal_is_empty());
   rows.push(serde_json::json!({"items":denied.maximum_items,"copy":denied.maximum_copy_bytes,"capacity":denied.maximum_capacity_bytes,"release":denied.maximum_release_bytes,"depth":denied.maximum_depth,"demandItems":1,"demandCopy":d.copy_bytes,"demandCapacity":d.capacity_bytes,"demandRelease":d.release_bytes,"demandDepth":d.depth,"admitted":false,"requested":physical.requested_bytes,"released":physical.released_bytes}));
  }
  let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());let progress=step.progress();assert!(progress.fits(grant));assert_eq!(physical.requested_bytes,progress.retained_capacity_bytes,"actual controlled child frame birth");assert_eq!(physical.released_bytes,progress.released_bytes,"actual original backing release");born+=physical.requested_bytes;freed+=physical.released_bytes;if matches!(step,RetainedCloneStep::Complete(_)){assert!(owner.terminal_is_empty());return(born,freed);}
 }panic!("original close did not converge")
}
#[test]
fn flow_original_prefix_four_currencies_and_cancelled_request(){
 let f=fixture();let grant=policy(&f);let corpus=wires();let wire=bytes(corpus["valid"][1]["hex"].as_str().unwrap());let mut rows=Vec::new();
 for fuel in f["workGrants"].as_array().unwrap(){for stop in f["stops"].as_array().unwrap(){let stop=stop.as_u64().unwrap()as usize;
  let((mut decoder,retained),physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let input=request(&wire,"flow");let retained=input.retained_input_bytes();(SemioFlowSnapshotDecode::begin(input).unwrap_or_else(|_|panic!("exact Flow source")),retained)});let mut born=physical.requested_bytes;let mut freed=physical.released_bytes;let cancel=root_cancel_token();let mut sequence=0;
  while decoder.consumed_bytes()<stop.min(wire.len()){let before=decoder.consumed_bytes();let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut cx=StepContext::new(OperationId(1),Generation(1),StepBudget::new(fuel.as_u64().unwrap()as u32,999),cancel.clone(),||Some(1),&mut sequence);decoder.step(&mut cx)});born+=physical.requested_bytes;freed+=physical.released_bytes;assert_eq!(physical.released_bytes,0);assert!(decoder.consumed_bytes()-before<=fuel.as_u64().unwrap()as usize);if step==SemioFlowSnapshotDecodeStep::Ready{break;}}
  cancel.cancel_now();let mut cx=StepContext::new(OperationId(1),Generation(1),StepBudget::new(1,999),cancel,||Some(1),&mut sequence);let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||decoder.step(&mut cx));assert_eq!(step,SemioFlowSnapshotDecodeStep::Rejected(MemberOpenDiagnostic::Cancelled));assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(decoder.retained_input_bytes(),retained);assert!(decoder.take_ready(&cx).is_none());let(birth,release)=close(&mut decoder,grant,&mut rows);assert_eq!(born+birth,freed+release);let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(decoder));assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));
 }}
 if let Ok(directory)=std::env::var("SEMIO_TEST_ARTIFACT_DIR"){std::fs::create_dir_all(&directory).unwrap();std::fs::write(std::path::Path::new(&directory).join("original-close.json"),serde_json::to_vec(&serde_json::json!({"rows":rows,"terminal":{"requested":0,"released":0}})).unwrap()).unwrap();}
 println!("[DEBUG] Flow actual original prefix18 interruption/work grants, five denied currencies, exact allocator birth/release receipts and zero terminal drop");
}
#[test]
fn flow_original_ready_handoff_preserves_source_identity_and_snapshot(){
 let f=fixture();let grant=policy(&f);let corpus=wires();let mut rows=Vec::new();for row in corpus["valid"].as_array().unwrap(){let wire=bytes(row["hex"].as_str().unwrap());let input=request(&wire,"flow");let pointer=input.expected().artifact_id.as_ptr();let mut decoder=SemioFlowSnapshotDecode::begin(input).unwrap_or_else(|_|panic!("exact Flow source"));let mut sequence=0;loop{let mut cx=StepContext::new(OperationId(1),Generation(1),StepBudget::new(7,999),root_cancel_token(),||Some(1),&mut sequence);match decoder.step(&mut cx){SemioFlowSnapshotDecodeStep::Pending{..}=>assert!(decoder.take_ready(&cx).is_none()),SemioFlowSnapshotDecodeStep::Ready=>break,other=>panic!("authored valid source rejected {other:?}")}}
 let mut cx=StepContext::new(OperationId(1),Generation(2),StepBudget::new(1,999),root_cancel_token(),||Some(1),&mut sequence);assert!(decoder.take_ready(&cx).is_none());assert_eq!(decoder.step(&mut cx),SemioFlowSnapshotDecodeStep::Rejected(MemberOpenDiagnostic::Stale));close(&mut decoder,grant,&mut rows);
 let input=request(&wire,"flow");let pointer=input.expected().artifact_id.as_ptr();let mut decoder=SemioFlowSnapshotDecode::begin(input).unwrap_or_else(|_|panic!("exact Flow source"));loop{let mut cx=StepContext::new(OperationId(1),Generation(1),StepBudget::new(4096,999),root_cancel_token(),||Some(1),&mut sequence);if decoder.step(&mut cx)==SemioFlowSnapshotDecodeStep::Ready{break;}}
 let cx=StepContext::new(OperationId(1),Generation(1),StepBudget::new(1,999),root_cancel_token(),||Some(1),&mut sequence);let((snapshot,mut input),physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||decoder.take_ready(&cx).unwrap());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(input.expected().artifact_id.as_ptr(),pointer);assert!(decoder.terminal_is_empty());assert_eq!(snapshot.encode_pack(),wire);let mut pending=Some(snapshot);let mut active=None;let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||store::artifact_retirement_admit_owned::<SemioFlowSnapshot>(&mut pending,&mut active,grant).unwrap());assert!(pending.is_none());assert_eq!(physical.requested_bytes,step.progress().retained_capacity_bytes);while active.is_some(){let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||store::artifact_retirement_box_close_step(&mut active,grant).unwrap());assert_eq!(physical.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(physical.released_bytes,step.progress().released_bytes);}close(&mut input,grant,&mut rows);let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(decoder));assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));
 }println!("[DEBUG] Flow exact native neutral wire, zero-heap original request/snapshot handoff, generation fence and funded original output close");
}#[test]
fn flow_original_faulted_prefix_and_foreign_request_close(){
 let f=fixture();let grant=policy(&f);let corpus=wires();let mut rows=Vec::new();for row in corpus["invalid"].as_array().unwrap(){let wire=bytes(row["hex"].as_str().unwrap());
  let(mut decoder,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||SemioFlowSnapshotDecode::begin(request(&wire,"flow")).unwrap_or_else(|_|panic!("original typed decoder")));let mut born=physical.requested_bytes;let mut freed=physical.released_bytes;let mut sequence=0;
  for _ in 0..100000{let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut cx=StepContext::new(OperationId(1),Generation(1),StepBudget::new(7,999),root_cancel_token(),||Some(1),&mut sequence);let step=decoder.step(&mut cx);assert!(decoder.take_ready(&cx).is_none());step});born+=physical.requested_bytes;freed+=physical.released_bytes;assert_eq!(physical.released_bytes,0);if matches!(step,SemioFlowSnapshotDecodeStep::Rejected(_)){break;}}
  let(birth,release)=close(&mut decoder,grant,&mut rows);assert_eq!(born+birth,freed+release);let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(decoder));assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));
 }
 let wire=bytes(corpus["valid"][0]["hex"].as_str().unwrap());let input=request(&wire,"text");let pointer=input.expected().artifact_id.as_ptr();let mut rejected=match SemioFlowSnapshotDecode::begin(input){Err(rejected)=>rejected,Ok(_)=>panic!("foreign original request must be refused")};assert_eq!(rejected.diagnostic,MemberOpenDiagnostic::Identity);assert_eq!(rejected.request.expected().artifact_id.as_ptr(),pointer);close(&mut rejected.request,grant,&mut rows);println!("[DEBUG] Flow malformed/capacity/identity faults retain original hydrated prefix and complete foreign request until funded physical close");
}